#!/usr/bin/env python3
"""Generate indexable bilingual HTML from manually maintained schools.json."""
import json
from html import escape as e
from pathlib import Path
import xml.etree.ElementTree as ET
ROOT=Path(__file__).resolve().parents[1]
data=json.loads((ROOT/'boarding-schools/schools.json').read_text());schools=data['schools']
def bi(k,n):return f'<span class="lang-ko">{e(k)}</span><span class="lang-en">{e(n)}</span>'
def value(f):
 if not f:return '<span class="unverified">'+bi('정보 확인 중','Not currently verified')+'</span>'
 v=bi(f['ko'],f['en'])
 if f.get('year') and f['year'] not in f['en']:v+=f'<small>{e(f["year"])}</small>'
 if f.get('basis'):v+='<small>'+bi(f['basis']['ko'],f['basis']['en'])+'</small>'
 if f.get('vat'):v+='<small>'+bi('VAT 포함 (과세 항목 기준)','VAT included where applicable')+'</small>'
 return v+f'<small class="school-source"><a href="{e(f["source"],quote=True)}" target="_blank" rel="noopener">{bi("공식 출처 ↗","Official source ↗")}</a> · {bi("확인","Checked")} {f["verified"]}</small>'
def row(k,n,f):return '<div><dt>'+bi(k,n)+'</dt><dd>'+value(f)+'</dd></div>'
def cta():return '<section class="cta-band"><div class="wrap cta-grid"><h2>'+bi('우리 아이에게 맞는 학교를 찾고 계신가요?','Looking for the right school for your child?')+'</h2><div class="cta-copy"><p>'+bi('공식 학교 정보는 출발점입니다. 학생의 학업 수준, 영어 능력, 성향과 장기적인 진학 목표를 함께 고려한 개별 상담이 필요하다면 My EDU Prep에 문의해 주세요.','Official information is a starting point. Contact My EDU Prep for advice considering academic level, English, personality and long-term goals.')+'</p><a class="button button-light" href="/contact/">'+bi('상담 문의하기','Enquire About a Consultation')+'</a></div></div></section>'
def shell(path,k,n,desc,body,mode):
 return f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(k)} | My EDU Prep</title><meta name="description" content="{e(desc,quote=True)}"><link rel="canonical" href="https://myeduprep.com{path}"><meta property="og:title" content="{e(k,quote=True)} | My EDU Prep"><meta property="og:description" content="{e(desc,quote=True)}"><meta property="og:type" content="website"><meta property="og:url" content="https://myeduprep.com{path}"><link rel="icon" href="/assets/favicon.svg"><link rel="stylesheet" href="/site.css?v=20260925-8"><link rel="stylesheet" href="/boarding-schools/boarding.css?v=20261021-1"><script src="/site.js?v=20261021-1" defer></script><script src="/boarding-schools/boarding.js?v=20261021-1" defer></script></head><body id="top" data-lang="ko" data-boarding-page="{mode}" data-title-ko="{e(k,quote=True)} | My EDU Prep" data-title-en="{e(n,quote=True)} | My EDU Prep" data-description-ko="{e(desc,quote=True)}" data-description-en="Explore official school information, programmes, boarding, fees and admissions with My EDU Prep."><site-header></site-header><main id="main">{body}{cta()}</main><site-footer></site-footer></body></html>'''
def hero(k,n,sk,sn):return '<section class="boarding-hero"><div class="wrap"><p class="eyebrow">My EDU Prep · School research</p><h1>'+bi(k,n)+'</h1><p class="lead">'+bi(sk,sn)+'</p><p class="guide-note">'+bi('공식 자료 기반 · 알파벳순 · 최종 확인','Official sources · Alphabetical order · Last checked')+' '+data['verifiedDate']+'</p></div></section>'
fields=[('학교 유형','School type','gender'),('연령·학년 범위','Age / year scope','ages'),('기숙 형태','Boarding','boarding'),('학업 과정','Programmes','programmes'),('연간 기숙학비','Annual boarding fee','fees')]
def card(s):
 slug=s['slug'];f=s['facts']
 return f'<article class="school-card" data-school="{slug}"><div class="school-visual" aria-hidden="true"><span>{e(s["name"].split()[0])}</span><small>BRITISH BOARDING SCHOOL GUIDE</small></div><div class="school-card-body"><h2><a href="/boarding-schools/{slug}/">{e(s["name"])}</a></h2><p class="school-location">{e(f["location"]["en"])}</p><p>'+bi(s['intro']['ko'],s['intro']['en'])+'</p><dl class="school-card-facts">'+''.join(row(k,n,f[key]) for k,n,key in fields)+f'</dl><div class="school-actions"><a class="arrow-link" href="/boarding-schools/{slug}/">'+bi('학교 상세 보기 →','View School Profile →')+f'</a><button type="button" class="button button-outline" data-compare-add="{slug}" aria-pressed="false">'+bi('비교에 추가','Add to Comparison')+'</button></div></div></article>'
def select(name,k,n,opts):
 return f'<label>{bi(k,n)}<select name="{name}"><option value="" data-ko="전체" data-en="All">전체</option>'+''.join(f'<option value="{e(str(v),quote=True)}" data-ko="{e(ko,quote=True)}" data-en="{e(en,quote=True)}">{e(ko)}</option>' for v,ko,en in opts)+'</select></label>'
filters='<label class="filter-search">'+bi('학교 이름 검색','Search school name')+'<input type="search" name="q" placeholder="Bede’s, Lancing…" autocomplete="off"></label>'
filters+=select('county','지역 / County','Location / County',[(c,c,c) for c in sorted({s['facts']['location']['value'] for s in schools})])
filters+=select('gender','학교 유형','Gender',[('boys','남학교','Boys'),('girls','여학교','Girls'),('coed','남녀공학','Co-educational')])
filters+=select('entry','입학 학년','Entry year',[(i,f'Year {i}',f'Year {i}') for i in range(7,13)])
filters+=select('programme','학업 과정','Academic programme',[(x,x,x) for x in ['GCSE','A-Level','IB','BTEC','CTEC','Pre-A-Level']])
filters+=select('fee','연간 학비 범위 (GBP)','Annual fee range (GBP)',[('0-50000','£50,000 미만','Below £50,000'),('50000-55000','£50,000–54,999','£50,000–54,999'),('55000-60000','£55,000–59,999','£55,000–59,999'),('60000-999999','£60,000 이상','£60,000 and above')])
filters+=select('boarding','기숙 형태','Boarding type',[('full','풀보딩','Full boarding'),('weekly','주중 기숙','Weekly boarding'),('flexi','유연 기숙','Flexi boarding')])
tray='<aside class="compare-tray" aria-label="School comparison"><div class="wrap"><div><strong>'+bi('나의 비교 목록','Your comparison')+'</strong><span data-selection-summary>0 / 3</span><div class="selected-schools" data-selected-schools></div></div><a class="button button-primary" data-compare-link href="/boarding-schools/compare/">'+bi('학교 비교하기','Compare Schools')+'</a></div></aside>'
body=hero('영국 보딩스쿨 가이드','British Boarding School Guide','학교의 명성보다 중요한 것은 우리 아이에게 맞는 교육 환경입니다. 영국 보딩스쿨의 학업 과정, 학비, 기숙사 생활, 입학 요건을 한눈에 살펴보고 비교해 보세요.','Explore and compare British boarding schools by academic programmes, fees, boarding arrangements and admissions requirements.')
body+='<section class="section-tight"><div class="wrap"><details class="guide-method"><summary>'+bi('자료와 학비 비교 기준','How to read the information and fees')+'</summary><p>'+bi('공식 학교 자료를 요약하며 순위·합격 가능성은 제공하지 않습니다. 연간 학비는 명시된 학년도의 수업·기숙비이며, 학기당 금액을 3배로 계산한 경우 표시합니다. 적용 학년·국제학생 구분·필수 식비·추가비용을 확인해 주세요. 학교 연령 범위는 모든 학년의 입학·기숙 가능 여부를 뜻하지 않습니다.','We summarise official school information without rankings or admission predictions. Annual tuition and boarding fees state their academic year; three-term calculations are identified. Check year-group scope, international rates, meals and extras. Age ranges do not guarantee entry or boarding in every year.')+'</p><p>'+bi('미확인 항목은 필터에서 일치하는 것으로 간주하지 않습니다. 서로 다른 시험·등급 지표·응시 인원은 단순 비교할 수 없습니다. 최종 비용과 지원 요건은 학교에 확인해 주세요.','Unverified fields do not count as filter matches. Exams with different measures or cohort sizes are not directly equivalent. Confirm final costs and requirements with each school.')+'</p></details><form class="school-filters" data-school-filters role="search">'+filters+'<button class="button button-outline" type="reset">'+bi('필터 초기화','Clear Filters')+'</button></form><p class="filter-help">'+bi('확인된 정보만 필터에 반영됩니다. 입학 학년은 공석·캠퍼스에 따라 달라질 수 있습니다.','Filters use verified information only. Entry years depend on availability and campus.')+'</p><p data-result-count role="status">8 '+bi('개 학교','schools')+'</p><div class="school-grid" data-school-grid>'+''.join(card(s) for s in schools)+'</div><p data-no-results hidden>'+bi('조건에 맞는 학교 정보가 없습니다. 필터를 줄여보세요.','No verified records match. Try fewer filters.')+'</p><noscript><p>'+bi('검색·필터·비교에는 JavaScript가 필요합니다. 학교 상세 페이지는 바로 읽을 수 있습니다.','Search, filters and comparison require JavaScript. All profiles remain readable.')+'</p></noscript><p data-guide-error hidden role="alert"></p></div></section>'+tray
(ROOT/'boarding-schools/index.html').write_text(shell('/boarding-schools/','영국 보딩스쿨 가이드','British Boarding School Guide','영국 보딩스쿨 8곳의 공식 자료를 기반으로 학업, 기숙사, 입학 요건과 학비를 비교하세요.',body,'directory'))
sections=[('학교 개요','School Overview',[('지역','Location','location'),*fields[:3],('학교 규모','School size','size')]),('학업 과정 및 결과','Academic Programmes & Results',[('제공 과정','Programmes','programmes'),('시험 결과','Exam results','results'),('대학 진학','University destinations','destinations')]),('입학 안내','Admissions',[('입학 학년','Entry years','entry'),('지원·평가·면접','Application & assessments','admissions'),('영어 요건','English requirements','english')]),('기숙사 생활','Boarding Life',[('기숙 형태','Boarding options','boarding'),('주말·방학','Weekends / holidays','weekends'),('하우스 구성','House system','houses')]),('학생 지원','Student Support',[('EAL / 영어 지원','EAL / English support','eal'),('학습 지원','Learning support','learning'),('생활·정서 지원','Pastoral care','pastoral')]),('학비 및 활동','Fees & Activities',[('연간 수업·기숙학비','Annual tuition & boarding','fees'),('추가비용','Additional charges','extras'),('활동·프로그램','Activities / programmes','activities')])]
for s in schools:
 slug=s['slug'];f=s['facts'];path=f'/boarding-schools/{slug}/';b=hero(s['name'],s['name'],s['intro']['ko'],s['intro']['en'])
 b+='<section class="section-tight"><div class="wrap school-profile"><div><p><a class="arrow-link" href="/boarding-schools/">'+bi('← 전체 학교 보기','← All Schools')+'</a></p>'
 for i,(k,n,fs) in enumerate(sections,1):b+=f'<section class="school-profile-section" id="section-{i}"><h2>{bi(k,n)}</h2><dl class="school-profile-facts">'+''.join(row(ko,en,f[key]) for ko,en,key in fs)+'</dl></section>'
 urls=sorted({v['source'] for v in f.values() if v and v.get('source')})
 b+='<section class="school-profile-section" id="sources"><h2>'+bi('공식 출처','Official Sources')+'</h2><p>'+bi('최종 확인','Last checked')+' '+data['verifiedDate']+f'</p><ul class="school-official-links"><li><a href="{s["website"]}" target="_blank" rel="noopener">'+bi('학교 공식 웹사이트 ↗','Official School Website ↗')+'</a></li>'+''.join(f'<li><a href="{e(u,quote=True)}" target="_blank" rel="noopener">{e(u)}</a></li>' for u in urls)+'</ul></section></div>'
 b+='<aside class="school-profile-aside"><p class="eyebrow">Your shortlist</p><h2>'+bi('함께 비교해 보세요','Build your comparison')+'</h2><p>'+bi('최대 3개 학교의 정보를 나란히 살펴볼 수 있습니다.','View up to three schools side by side.')+f'</p><button class="button button-primary" type="button" data-compare-add="{slug}" aria-pressed="false">'+bi('학교 비교하기','Compare This School')+'</button><a class="arrow-link" data-compare-link href="/boarding-schools/compare/">'+bi('비교표 열기 →','Open comparison →')+'</a><a class="arrow-link" href="/contact/">'+bi('상담 문의하기 →','Enquire About a Consultation →')+'</a><nav aria-label="Profile sections">'+''.join(f'<a href="#section-{i}">{bi(k,n)}</a>' for i,(k,n,_) in enumerate(sections,1))+'<a href="#sources">'+bi('공식 출처','Official Sources')+'</a></nav></aside></div></section>'+tray
 out=ROOT/path.strip('/')/'index.html';out.parent.mkdir(parents=True,exist_ok=True);out.write_text(shell(path,s['name']+' 학교 정보',s['name']+' School Profile',s['intro']['ko'],b,'profile'))
b=hero('학교 비교하기','Compare Schools','학교의 순위 대신, 우리 아이에게 중요한 조건을 나란히 살펴보세요.','Compare the details that matter to your child, without school rankings.')
b+='<section class="section-tight"><div class="wrap"><p>'+bi('최대 3개 학교를 선택하세요. 모바일에서는 두 학교씩 볼 수 있습니다.','Select up to three schools. On mobile, view two at a time.')+'</p><div class="comparison-controls"><label for="compare-school">'+bi('학교 선택','Choose a school')+'</label><select id="compare-school"><option value="" data-ko="학교를 선택해 주세요" data-en="Select a school">학교를 선택해 주세요</option>'+''.join(f'<option value="{s["slug"]}">{e(s["name"])}</option>' for s in schools)+'</select><button class="button button-primary" type="button" data-add-selected>'+bi('비교에 추가','Add to Comparison')+'</button><a class="arrow-link" href="/boarding-schools/">'+bi('전체 학교 보기 →','Browse Schools →')+'</a></div><div class="selected-schools" data-selected-schools></div><p data-comparison-status role="status"></p><div class="mobile-pair" data-mobile-pair hidden><label for="compare-pair">'+bi('모바일 비교할 두 학교','Two schools to view on mobile')+'</label><select id="compare-pair"></select></div><div class="comparison-scroll" tabindex="0" aria-label="School comparison table" data-comparison-table></div><p class="guide-note">'+bi('학비는 GBP 기준이며 학년도·적용 대상을 확인해 주세요. 지표·연도가 다른 시험 결과는 직접 비교할 수 없습니다. 미확인 값은 추정하지 않습니다.','Fees are in GBP; check year and scope. Exam results with different measures or years are not directly equivalent. Unverified values are not estimated.')+'</p><label class="share-comparison" for="share-url">'+bi('비교 링크 공유','Share this comparison')+'<input id="share-url" type="url" readonly></label><button class="button button-outline" type="button" data-copy-comparison>'+bi('링크 복사','Copy Link')+'</button><p data-copy-status role="status"></p><p data-guide-error hidden role="alert"></p><noscript><p>'+bi('비교 기능에는 JavaScript가 필요합니다.','Comparison requires JavaScript.')+'</p></noscript></div></section>'
out=ROOT/'boarding-schools/compare/index.html';out.parent.mkdir(exist_ok=True);out.write_text(shell('/boarding-schools/compare/','학교 비교하기','Compare Boarding Schools','영국 보딩스쿨 최대 3곳의 학비, 학업, 기숙 형태와 입학 요건을 비교하세요.',b,'compare'))
ns='http://www.sitemaps.org/schemas/sitemap/0.9';ET.register_namespace('',ns);tree=ET.parse(ROOT/'sitemap.xml');r=tree.getroot();existing={n.text for n in r.findall(f'{{{ns}}}url/{{{ns}}}loc')}
for p in ['/boarding-schools/','/boarding-schools/compare/']+[f'/boarding-schools/{s["slug"]}/' for s in schools]:
 u='https://myeduprep.com'+p
 if u not in existing:ET.SubElement(ET.SubElement(r,f'{{{ns}}}url'),f'{{{ns}}}loc').text=u
ET.indent(tree,space='  ');tree.write(ROOT/'sitemap.xml',encoding='unicode',xml_declaration=True)
print('Generated directory, comparison and 8 static profiles.')
